370	    /**
371	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
372	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
373	     * hand is already past, stay drafts.
374	     */
375	    @Transactional
376	    public void sendAllDrafts(Long clientId) {
377	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
378	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
379	                        && !invoice.dueDatePassedBy(today.date()))
380	                .forEach(invoice -> {
381	                    if (!invoice.isCreditNote()) {
382	                        markSent(invoice);
383	                    } else if (creditNoteRefusal(invoice) == null) {
384	                        issue(invoice);
385	                    }
386	                });
387	    }
388	
389	    /**
390	     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
391	     * invoice (not void) that still owes at least the credit note's grand total.
392	     */
393	    private String creditNoteRefusal(Invoice note) {
394	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
395	        if (original == null || original.isDraft() || original.isVoid()) {
396	            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
397	        }
398	        // Read again what it has been credited: another credit note may just have been issued against it.
399	        entityManager.refresh(original);
400	        BigDecimal rate = taxRate.percent();
401	        BigDecimal due = original.amountDue(paid(List.of(original)).get(original.getId()), rate);
402	        BigDecimal total = note.total(rate);
403	        if (total.compareTo(due) > 0) {
404	            return "The credit note's total of $" + total.toPlainString() + " is more than the $"
405	                    + due.setScale(2, RoundingMode.HALF_UP).toPlainString() + " " + original.number()
406	                    + " still owes.";
407	        }
408	        return null;
409	    }
410	
411	    /** Issues the draft credit note today, its grand total coming off its original, and records it in the audit. */
412	    private void issue(Invoice note) {
413	        BigDecimal rate = taxRate.percent();
414	        note.markIssued(today.date(), rate);
415	        invoices.saveAndFlush(note);
416	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
417	                + note.getCreditOf() + " total=" + note.total(rate).toPlainString());
418	    }
419	
420	    /**
421	     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
422	     * client's credit on it (see {@link #applyCredit}).
423	     */
424	    private void markSent(Invoice invoice) {
425	        LocalDate issued = today.date();
426	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
427	        invoices.saveAndFlush(invoice);
428	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
429	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
430	        applyCredit(invoice);
431	    }
432	
433	    /**
434	     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
435	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
436	     */
437	    private void applyCredit(Invoice invoice) {
438	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
439	        LocalDate now = today.date();
440	        boolean used = false;
441	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
442	            if (due.signum() <= 0) {
443	                break;
444	            }
445	            BigDecimal credit = payment.credit();
446	            if (credit.signum() <= 0) {
447	                continue;
448	            }
449	            BigDecimal part = credit.min(due);
450	            payment.apply(invoice.getId(), part, now);
451	            payments.saveAndFlush(payment);
452	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
453	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
454	            due = due.subtract(part);
455	            used = true;
456	        }
457	        if (used) {
458	            recordWriteOff(invoice);
459	        }
460	    }
