462	    /**
463	     * Records a deposit of the amount on the date from the client: the whole amount is held on the
464	     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
465	     * client. The amount has already been checked; a date after today is refused.
466	     */
467	    @Transactional
468	    public Optional<Payment> recordDeposit(Long clientId, BigDecimal amount, LocalDate date) {
469	        if (clients.findById(clientId).isEmpty()) {
470	            return Optional.empty();
471	        }
472	        LocalDate now = today.date();
473	        if (date.isAfter(now)) {
474	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
475	        }
476	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
477	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
478	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
479	        return Optional.of(payment);
480	    }
481	
482	    /**
483	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
484	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
485	     * such client. The amount has already been checked; a date after today or before a payment it
486	     * would come from, or an amount more than the client's credit, is refused.
487	     */
488	    @Transactional
489	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
490	        if (clients.findById(clientId).isEmpty()) {
491	            return Optional.empty();
492	        }
493	        LocalDate now = today.date();
494	        if (date.isAfter(now)) {
495	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
496	        }
497	        List<Payment> from = new ArrayList<>();
498	        List<BigDecimal> parts = new ArrayList<>();
499	        BigDecimal left = amount;
500	        BigDecimal credit = BigDecimal.ZERO;
501	        for (Payment payment : payments.findForClient(clientId)) {
502	            BigDecimal unused = payment.credit();
503	            if (unused.signum() <= 0) {
504	                continue;
505	            }
506	            credit = credit.add(unused);
507	            if (left.signum() <= 0) {
508	                continue;
509	            }
510	            BigDecimal part = unused.min(left);
511	            if (date.isBefore(payment.getDate())) {
512	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
513	                        + payment.getDate() + " it would come from.");
514	            }
515	            from.add(payment);
516	            parts.add(part);
517	            left = left.subtract(part);
518	        }
519	        if (left.signum() > 0) {
520	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
521	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
522	        }
523	        for (int i = 0; i < from.size(); i++) {
524	            Payment payment = from.get(i);
525	            payment.refund(parts.get(i));
526	            payments.saveAndFlush(payment);
527	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
528	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
529	        }
530	        return Optional.of(clientId);
531	    }
532	
533	    /** The unused credit of each client that has any, by client id. */
534	    @Transactional(readOnly = true)
535	    public Map<Long, BigDecimal> credits() {
536	        Map<Long, BigDecimal> credits = new HashMap<>();
537	        for (Payment payment : payments.findNotReversed()) {
538	            BigDecimal credit = payment.credit();
539	            if (credit.signum() > 0) {
540	                credits.merge(payment.getClientId(), credit, BigDecimal::add);
541	            }
542	        }
543	        return credits;
544	    }
