546	    /**
547	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
548	     * draft, an invoice already void, or one with any payment is refused.
549	     */
550	    @Transactional
551	    public Optional<Invoice> voidInvoice(Long invoiceId) {
552	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
553	        found.ifPresent(invoice -> {
554	            if (invoice.isVoid()) {
555	                throw new InvoiceRejectedException("This invoice is already void.");
556	            }
557	            if (invoice.isDraft()) {
558	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
559	            }
560	            if (invoice.isCreditNote()) {
561	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
562	            }
563	            if (invoice.hasCreditNotesIssued()) {
564	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
565	            }
566	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
567	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
568	            }
569	            invoice.markVoid();
570	            invoices.saveAndFlush(invoice);
571	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
572	        });
573	        return found;
574	    }
