582	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
583	    @Transactional(readOnly = true)
584	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
585	        Map<Long, LocalDate> paidOn = new HashMap<>();
586	        if (list.isEmpty()) {
587	            return paidOn;
588	        }
589	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
590	        BigDecimal rate = taxRate.percent();
591	        for (Invoice i : list) {
592	            LocalDate on = i.paidOn(found, rate);
593	            if (on != null) {
594	                paidOn.put(i.getId(), on);
595	            }
596	        }
