600	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
601	    @Transactional(readOnly = true)
602	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
603	        Map<Long, BigDecimal> paid = new HashMap<>();
604	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
605	        if (!list.isEmpty()) {
606	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
607	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
608	            }
609	        }
610	        return paid;
611	    }
