613	    /**
614	     * Records a payment of the amount on the date against a sent invoice that still has something
615	     * due, and records it in the audit; empty if no such invoice. The amount has already been
616	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
617	     * invoice already paid, or a date after today
618	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
619	     * already been checked; one that belongs to a different invoice is refused.
620	     */
621	    @Transactional
622	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
623	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
624	        found.ifPresent(invoice -> {
625	            if (invoice.isDraft()) {
626	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
627	            }
628	            if (invoice.isVoid()) {
629	                throw new InvoiceRejectedException("A void invoice takes no payments.");
630	            }
631	            if (invoice.isCreditNote()) {
632	                throw new InvoiceRejectedException("A credit note takes no payments.");
633	            }
634	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
635	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
636	            if (due.signum() <= 0) {
637	                throw new InvoiceRejectedException("This invoice has already been paid.");
638	            }
639	            BigDecimal applied = amount.min(due);
640	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
641	                throw new InvoiceRejectedException("A part payment must be at least $"
642	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
643	                        + " (10% of the total), unless it settles the invoice.");
644	            }
645	            LocalDate now = today.date();
646	            if (date.isAfter(now)) {
647	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
648	            }
649	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
650	                throw new InvoiceRejectedException(
651	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
652	            }
653	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
654	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
655	                        + " is the reference of a different invoice; this invoice's is "
656	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
657	            }
658	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
659	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
660	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
661	            recordWriteOff(invoice);
662	            recordCreditHeld(payment);
663	        });
664	        return found;
665	    }
666	
667	    /**
668	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
669	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
670	     * paying each off in full before the next.
671	     * What it pays beyond everything the client owes is held on the client's account as credit; the
672	     * rest is checked and recorded as a split payment over the invoices it reaches.
673	     * References (empty when none, each already checked) instead limit the payment to the client's
674	     * invoices with those references, applied in the same order; one that is not the reference of any
675	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
676	     * as credit.
677	     * The payment keeps the reference of the first invoice it reaches.
678	     */
679	    @Transactional
680	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
681	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
682	        List<Invoice> candidates = ofClient;
683	        if (!references.isEmpty()) {
684	            Set<Long> named = new HashSet<>();
685	            for (String reference : references) {
686	                Invoice invoice = ofClient.stream()
687	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
688	                        .findFirst()
689	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
690	                                + " is not the reference of any of this client's invoices."));
691	                String number = InvoiceNumber.of(invoice.getId());
692	                if (invoice.isDraft()) {
693	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
694	                }
695	                if (invoice.isVoid()) {
696	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
697	                }
698	                if (invoice.isCreditNote()) {
699	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
700	                }
701	                named.add(invoice.getId());
702	            }
703	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
704	        }
705	        List<Invoice> sent = candidates.stream()
706	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
707	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
708	                        .thenComparing(Invoice::getId))
709	                .toList();
710	        Map<Long, BigDecimal> paid = paid(sent);
711	        BigDecimal owed = BigDecimal.ZERO;
712	        BigDecimal left = amount;
713	        List<PaymentAllocation> parts = new ArrayList<>();
714	        for (Invoice invoice : sent) {
715	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
716	            if (due.signum() <= 0) {
717	                continue;
718	            }
719	            owed = owed.add(due);
720	            if (left.signum() > 0) {
721	                BigDecimal part = left.min(due);
722	                parts.add(new PaymentAllocation(invoice.getId(), part));
723	                left = left.subtract(part);
724	            }
725	        }
726	        if (owed.signum() <= 0) {
727	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
728	                    : "Those invoices have already been paid.");
729	        }
730	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
731	        return recordSpread(clientId, amount, date, reference, parts, true);
732	    }
733	
734	    /**
735	     * Records one payment of the amount on the date spread over several of the client's invoices, and
736	     * records each part in the audit. The amounts have already been checked to be more than zero; they
737	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
738	     * and be no more than what it still has due. The date must be no later than today nor before any
739	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
740	     * be the reference of one of the invoices.
741	     */
742	    @Transactional
743	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
744	            List<PaymentAllocation> parts) {
745	        return recordSpread(clientId, amount, date, reference, parts, false);
746	    }
747	
748	    /**
749	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
750	     * credit may be held the parts may add up to less than the payment: the rest is held on the
751	     * client's account as credit and recorded in the audit.
752	     */
753	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
754	            List<PaymentAllocation> parts, boolean holdCredit) {
755	        if (parts.isEmpty()) {
756	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
757	        }
758	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
759	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
760	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
761	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
762	        }
763	        LocalDate now = today.date();
764	        if (date.isAfter(now)) {
765	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
766	        }
767	        Set<Long> seen = new HashSet<>();
768	        List<Invoice> spreadOver = new ArrayList<>();
769	        for (PaymentAllocation part : parts) {
770	            if (!seen.add(part.getInvoiceId())) {
771	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
772	            }
773	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
774	                    .filter(i -> i.getClientId().equals(clientId))
775	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
776	            String number = InvoiceNumber.of(invoice.getId());
777	            if (invoice.isDraft()) {
778	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
779	            }
780	            if (invoice.isVoid()) {
781	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
782	            }
783	            if (invoice.isCreditNote()) {
784	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
785	            }
786	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
787	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
788	            if (part.getAmount().compareTo(due) > 0) {
789	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
790	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
791	            }
792	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
793	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
794	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
795	                        + " (10% of its total), unless it settles the invoice.");
796	            }
797	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
798	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
799	                        + " (" + invoice.getIssueDate() + ").");
800	            }
801	            spreadOver.add(invoice);
802	        }
803	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
804	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
805	                    + " is not the reference of any of the invoices being paid.");
806	        }
807	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
808	        for (PaymentAllocation part : parts) {
809	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
810	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
811	        }
812	        spreadOver.forEach(this::recordWriteOff);
813	        recordCreditHeld(payment);
814	        return payment;
815	    }
816	
817	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
818	    private void recordCreditHeld(Payment payment) {
819	        BigDecimal credit = payment.credit();
820	        if (credit.signum() > 0) {
821	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
822	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
823	        }
824	    }
825	
826	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
827	    private void recordWriteOff(Invoice invoice) {
828	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
